package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	s, _ := reader.ReadString('\n')
	// Remove trailing newline
	for len(s) > 0 && (s[len(s)-1] == '\n' || s[len(s)-1] == '\r') {
		s = s[:len(s)-1]
	}

	n := len(s)
	if n == 0 {
		fmt.Println(0)
		return
	}

	// Generate all cyclic shifts and count distinct ones
	seen := make(map[string]bool)
	for i := 0; i < n; i++ {
		// Cyclic shift: move last i characters to the front
		// Equivalent to s[n-i:] + s[:n-i]
		shifted := s[n-i:] + s[:n-i]
		seen[shifted] = true
	}

	fmt.Println(len(seen))
}
